interface ModalHandle {
  open: () => void;
  close: () => void;
  isOpen: boolean;
}

const Modal = forwardRef<ModalHandle, { title: string }>(
  ({ title }, ref) => {
    const [isOpen, setIsOpen] = useState(false);

    useImperativeHandle(ref, () => ({
      get isOpen() {
        return isOpen;
      },
      open() {
        setIsOpen(true);
      },
      close() {
        setIsOpen(false);
      },
    }), [isOpen]);

    if (!isOpen) return null;
    return <div className="modal">{title}</div>;
  }
);

